reply:
Your catalog has no generic container that can hold other components, so I built the page as four stacked surfaces, one per section: hero, features, testimonial, and call to action.

<a2ui-json>
[
  {
    "version": "v0.9.1",
    "createSurface": {
      "surfaceId": "landing_hero",
      "catalogId": "https://a2uicatalog.ai/catalog/c-marketing-commerce.json"
    }
  },
  {
    "version": "v0.9.1",
    "updateComponents": {
      "surfaceId": "landing_hero",
      "components": [
        {
          "id": "root",
          "component": "gradient_hero",
          "badge": "New: Flow 2.0",
          "title": "Ship projects faster, together",
          "subtitle": "Flow brings your tasks, docs, and team conversations into one calm workspace so nothing slips through the cracks.",
          "align": "center"
        }
      ]
    }
  }
]
</a2ui-json>

